import {escapeHTML as e,uid} from './store.js';
export function parseMusicLink(value){const u=new URL(value);if(!['https:','http:'].includes(u.protocol))throw Error('Cole um link do Spotify ou YouTube.');const host=u.hostname.replace(/^www\./,'');if(host==='open.spotify.com'){const parts=u.pathname.split('/').filter(Boolean).filter(p=>!p.startsWith('intl-'));if(['track','playlist','album','episode'].includes(parts[0])&&/^[a-zA-Z0-9]+$/.test(parts[1]||''))return {kind:'spotify',source:`https://open.spotify.com/embed/${parts[0]}/${parts[1]}`};}if(['youtube.com','m.youtube.com','youtu.be'].includes(host)){const id=host==='youtu.be'?u.pathname.slice(1):u.searchParams.get('v')||u.pathname.match(/^\/(?:shorts|embed)\/([^/]+)/)?.[1];if(/^[\w-]{11}$/.test(id||''))return {kind:'youtube',source:`https://www.youtube.com/embed/${id}?rel=0`};}throw Error('Use um link de música/playlist do Spotify ou de vídeo do YouTube.');}
function database(){return new Promise((resolve,reject)=>{const request=indexedDB.open('aethra.music',1);request.onupgradeneeded=()=>request.result.createObjectStore('files');request.onsuccess=()=>resolve(request.result);request.onerror=()=>reject(Error('Não foi possível abrir o armazenamento de músicas.'));});}
async function fileStore(mode,id,value){const db=await database();try{return await new Promise((resolve,reject)=>{const tx=db.transaction('files',mode),store=tx.objectStore('files');let result;const request=mode==='readonly'?store.get(id):value?store.put(value,id):store.delete(id);request.onsuccess=()=>result=request.result;tx.oncomplete=()=>resolve(result);tx.onerror=()=>reject(Error('Não foi possível salvar o arquivo. Verifique o espaço disponível.'));tx.onabort=tx.onerror;});}finally{db.close();}}
export function initMusic(){
 let tracks=[];try{const saved=JSON.parse(localStorage.getItem('aethra.music.v1'));if(Array.isArray(saved))tracks=saved.filter(t=>t&&typeof t.id==='string'&&typeof t.title==='string'&&['file','spotify','youtube'].includes(t.kind));}catch{}
 const root=document.createElement('div');root.className='music-widget';root.innerHTML=`<button type="button" class="music-toggle" aria-label="Abrir player de música" aria-expanded="false">♫ <span>Música</span></button><section class="music-panel" aria-label="Player de música" hidden><header><div><small>TRILHA DO SEU UNIVERSO</small><h2>Sua playlist</h2></div><button type="button" class="music-close" aria-label="Recolher player">×</button></header><div class="music-stage"><span>♫</span><p>Escolha uma música para acompanhar sua escrita.</p></div><div class="music-navigation"><button type="button" data-music-prev aria-label="Faixa anterior">‹ Anterior</button><span class="music-current">Nenhuma faixa</span><button type="button" data-music-next aria-label="Próxima faixa">Próxima ›</button></div><form class="music-add"><input name="title" placeholder="Nome da música (opcional)" aria-label="Nome da música" maxlength="120"><div><input name="url" type="url" placeholder="Link do Spotify ou YouTube" aria-label="Link da música" required><button type="submit" aria-label="Adicionar link à playlist">＋</button></div></form><label class="music-import">＋ Importar MP3 / MP4<input type="file" accept="audio/mpeg,audio/mp3,video/mp4,audio/mp4,.mp3,.mp4,.m4a" multiple hidden></label><p class="music-status" role="status"></p><div class="music-list" aria-label="Faixas da playlist"></div><small class="music-help">Arquivos ficam neste navegador. Spotify e YouTube usam seus players e podem exigir login ou limitar a reprodução. Backup de universos não inclui músicas.</small></section>`;document.body.append(root);
 const $=selector=>root.querySelector(selector),panel=$('.music-panel'),stage=$('.music-stage'),status=$('.music-status');let current='',objectURL='',generation=0;
 const tell=message=>status.textContent=message;
 function save(){try{localStorage.setItem('aethra.music.v1',JSON.stringify(tracks));return true;}catch{tell('Não foi possível salvar a playlist. Armazenamento cheio.');return false;}}
 function draw(){ $('.music-list').innerHTML=tracks.map(t=>`<div class="music-track ${t.id===current?'active':''}"><button type="button" data-play="${e(t.id)}"><span>♫</span><span><strong>${e(t.title)}</strong><small>${t.kind==='file'?'Arquivo local':t.kind==='spotify'?'Spotify':'YouTube'}</small></span></button><button type="button" data-remove="${e(t.id)}" aria-label="Remover ${e(t.title)} da playlist">×</button></div>`).join('')||'<p class="music-empty">Sua playlist está vazia. Cole um link ou importe seus arquivos.</p>';root.querySelectorAll('[data-play]').forEach(b=>b.onclick=()=>play(b.dataset.play));root.querySelectorAll('[data-remove]').forEach(b=>b.onclick=async()=>{const t=tracks.find(x=>x.id===b.dataset.remove);if(!t)return;if(current===t.id)stop();tracks=tracks.filter(x=>x!==t);save();draw();if(t.kind==='file')try{await fileStore('readwrite',t.id);}catch{tell('Faixa removida da playlist.');}});}
 function stop(){generation++;stage.querySelector('audio,video')?.pause();stage.innerHTML='<span>♫</span><p>Escolha uma música para acompanhar sua escrita.</p>';if(objectURL){URL.revokeObjectURL(objectURL);objectURL='';}current='';$('.music-current').textContent='Nenhuma faixa';}
 async function play(id){const track=tracks.find(t=>t.id===id);if(!track)return;stop();current=id;const request=++generation;$('.music-current').textContent=track.title;draw();tell('');try{if(track.kind==='file'){const blob=await fileStore('readonly',track.id);if(request!==generation)return;if(!blob)throw Error('Arquivo indisponível neste navegador. Importe-o novamente.');objectURL=URL.createObjectURL(blob);const media=document.createElement(track.video?'video':'audio');media.controls=true;media.src=objectURL;media.onended=()=>next(1);media.onerror=()=>tell('O navegador não conseguiu reproduzir este formato.');stage.replaceChildren(media);media.play().catch(()=>tell('Clique em reproduzir para iniciar a música.'));}else{const verified=parseMusicLink(track.source.replace('/embed/track/','/track/').replace('/embed/playlist/','/playlist/').replace('/embed/album/','/album/').replace('/embed/episode/','/episode/'));const frame=document.createElement('iframe');frame.src=verified.source;frame.title=track.title;frame.allow='autoplay; clipboard-write; encrypted-media; fullscreen; picture-in-picture';frame.referrerPolicy='strict-origin-when-cross-origin';frame.allowFullscreen=true;frame.className=track.kind;stage.replaceChildren(frame);}}catch(error){tell(error.message);}}
 function next(delta){if(!tracks.length)return;const index=tracks.findIndex(t=>t.id===current);play(tracks[(index<0?0:(index+delta+tracks.length)%tracks.length)].id);}
 function toggle(open){panel.hidden=!open;$('.music-toggle').setAttribute('aria-expanded',String(open));}$('.music-toggle').onclick=()=>toggle(panel.hidden);$('.music-close').onclick=()=>toggle(false);$('[data-music-prev]').onclick=()=>next(-1);$('[data-music-next]').onclick=()=>next(1);
 $('.music-add').onsubmit=event=>{event.preventDefault();try{const data=new FormData(event.target),parsed=parseMusicLink(String(data.get('url')).trim());tracks.push({id:uid(),title:String(data.get('title')).trim()||`${parsed.kind==='spotify'?'Spotify':'YouTube'} · Faixa ${tracks.length+1}`,...parsed});save();draw();event.target.reset();tell('Link adicionado. Selecione a faixa e use o player para reproduzir.');}catch(error){tell(error.message);}};
 $('.music-import input').onchange=async event=>{const input=event.target;input.disabled=true;try{for(const file of input.files){if(!/\.(mp3|mp4|m4a)$/i.test(file.name)){tell('Escolha arquivos MP3, MP4 ou M4A.');continue;}const id=uid();await fileStore('readwrite',id,file);tracks.push({id,kind:'file',title:file.name.replace(/\.[^.]+$/,''),video:/\.mp4$/i.test(file.name)});save();draw();}tell('Importação concluída. Selecione uma faixa para reproduzir.');}catch(error){tell(error.message);}finally{input.disabled=false;input.value='';}};draw();window.addEventListener('pagehide',()=>{if(objectURL)URL.revokeObjectURL(objectURL);});
}
